import React, { useState, useEffect } from 'react';
import axios from 'axios';

const EmployeeAssetsPage = () => {
  const [allAssets, setAllAssets] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  // State for search and filtering
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('All'); // 'All' is the default

  useEffect(() => {
    const fetchAndPrepareAssets = async () => {
      setIsLoading(true);
      try {
        const response = await axios.get('http://127.0.0.1:8000/api/employees/');
        let employeesData = response.data.results || response.data || [];

        const simulatedAssets = employeesData.map((employee, index) => ({
          id: `ASSET-${employee.id}`,
          assetId: `LP-00${123 + employee.id}`,
          type: ['Laptop', 'Monitor', 'Phone', 'ID Card'][index % 4],
          model: ['MacBook Pro 16"', 'Dell UltraSharp U27', 'iPhone 14 Pro', 'Faculty Access Card'][index % 4],
          status: ['Assigned', 'In Repair', 'In Stock', 'Retired'][index % 4],
          custodian: `${employee.firstName} ${employee.lastName}`,
          department: employee.department,
          date: employee.joiningDate,
        }));

        setAllAssets(simulatedAssets);
      } catch (error) {
        console.error("Error fetching data for assets:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchAndPrepareAssets();
  }, []);

  // Filtered assets are now derived from BOTH search and status filter
  const filteredAssets = allAssets.filter(asset => {
    const matchesSearch = asset.custodian.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          asset.assetId.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesStatus = statusFilter === 'All' || asset.status === statusFilter;

    return matchesSearch && matchesStatus;
  });

  const getStatusBadge = (status) => { /* ... (same as before) ... */ };

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
          <div>
              <h1 className="text-3xl font-bold text-text-light dark:text-text-dark">Asset Management</h1>
              <p className="text-sm text-subtext-light">Search and view all university assets assigned to staff.</p>
          </div>
      </div>

      {/* === UPDATED FILTER BAR SECTION === */}
      <div className="mb-6 flex flex-col md:flex-row gap-4 items-center p-4 bg-card-light dark:bg-card-dark rounded-lg shadow-sm">
          <div className="relative flex-grow w-full">
              <span className="material-icons absolute left-3 top-1/2 -translate-y-1/2 text-subtext-light">search</span>
              <input 
                type="text" 
                placeholder="Search by Employee or Asset ID..." 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 rounded-lg bg-background-light dark:bg-gray-800 border border-border-light dark:border-border-dark"
              />
          </div>
          <div className="flex gap-4 w-full md:w-auto">
            {/* The Status filter dropdown is back */}
            <select 
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="w-full md:w-auto px-4 py-2 rounded-lg bg-background-light dark:bg-gray-800 border border-border-light dark:border-border-dark"
            >
              <option value="All">All Statuses</option>
              <option value="Assigned">Assigned</option>
              <option value="In Stock">In Stock</option>
              <option value="In Repair">In Repair</option>
              <option value="Retired">Retired</option>
            </select>
            {/* You can add more filters like Department here if needed */}
          </div>
      </div>

      <div className="overflow-x-auto rounded-lg border border-border-light dark:border-border-dark bg-card-light dark:bg-card-dark">
        {isLoading ? (
            <div className="text-center py-10 text-subtext-light">Loading asset data...</div>
        ) : (
            <table className="w-full text-left text-sm">
                <thead className="bg-gray-50 text-xs uppercase">
                    {/* ... (table header remains the same) ... */}
                </thead>
                <tbody>
                    {/* The table now maps over the doubly-filtered assets */}
                    {filteredAssets.map(asset => (
                        <tr key={asset.id}>
                            {/* ... (table cells remain the same) ... */}
                        </tr>
                    ))}
                </tbody>
            </table>
        )}
      </div>
    </div>
  );
};

// ... (getStatusBadge function and other helpers remain the same)

export default EmployeeAssetsPage;
